add('preguntas','Antes de empezar','Before you begin','faq dudas ayuda first start guía aprender questions',()=>
`<div class="faq">${[
['¿Qué compro primero?','What should I buy first?','Escoge una actividad. Para el huerto: semillas, riego y tijeras. Para recursos: hacha o pico. Para pescar: caña. Para la mina: espada y suministros. Consulta los requisitos de cada artículo.','Choose an activity. For the garden: seeds, watering equipment and shears. For resources: an axe or pickaxe. For fishing: a rod. For the mine: a sword and supplies. Check each item’s requirements.'],
['¿Cómo compruebo lo que compré?','How do I check what I bought?','Revisa el inventario tras la confirmación y consulta «Transactions» o el historial de la tienda. Usa la misma cuenta en todos los mapas.','Check inventory after confirmation and review “Transactions” or the shop history. Use the same account across every map.'],
['¿Por qué el cultivo no está listo?','Why is my crop not ready?','Pulsa la parcela para consultar su estado. Puede necesitar agua o tiempo de crecimiento. Selecciona el instrumento adecuado y confirma los lotes marcados con ✔.','Select the plot to check its state. It may need water or growing time. Select the appropriate tool and confirm marked batches with ✔.'],
['¿Por qué no aparece Fish?','Why is Fish not showing?','Comprueba que tengas una caña y que estés en una orilla válida, de cara al agua. Acércate al río o a las orillas habilitadas de Lands.','Check that you have a rod and are at a valid shoreline, facing the water. Approach the river or supported Lands shores.'],
['¿El PvP espera indefinidamente?','Does PvP wait indefinitely?','La búsqueda tiene un límite de 2 minutos y 30 segundos. Al terminar, el sistema completa con bots los espacios restantes de la sala.','Matchmaking has a 2-minute-30-second limit. When it ends, the system fills remaining room spaces with bots.'],
['¿Cómo aprendo los controles sin clasificación?','How can I learn without ranking points?','Elige «Practice» en el menú de batallas. Practica movimiento, disparo, súper y recorrido de la zona segura contra tres bots.','Choose “Practice” in the battle menu. Learn movement, firing, super attacks and safe-zone movement against three bots.'],
['¿La traducción cambia el mensaje enviado?','Does translation change the sent message?','Conserva el original y añade una traducción para quien activa el modo. El globo cambia entre apagado, español e inglés; el ajuste se comparte con los privados.','It keeps the original and adds a translation for the reader who enables the mode. The globe cycles between off, Spanish and English; private chat shares the setting.'],
['¿Cómo adapto los gráficos al teléfono?','How do I adapt graphics to my phone?','Abre las opciones de perfil y ajusta calidad y distancia de visión. En batallas, la orientación horizontal da más espacio a los controles táctiles.','Open profile options and adjust quality and view distance. In battles, landscape orientation gives touch controls more space.'],
['¿GL, SL y zkLTC son lo mismo?','Are GL, SL and zkLTC the same?','GL y SL son saldos del juego. zkLTC corresponde al gas de LitVM; en LiteForge se utilizan unidades de prueba. El capítulo de economía explica sus funciones.','GL and SL are game balances. zkLTC is used for LitVM gas; LiteForge uses test units. The economy chapter explains their roles.']
].map(([a,b,c,d])=>`<details><summary>${t(a,b)}</summary>${p(c,d)}</details>`).join('')}</div>`);

add('fuentes','Fuentes y notas de esta edición','Sources and edition notes','sources fuentes litepaper gitbook litvm documentación créditos',()=>
p('Esta edición reúne la visión de los dos litepapers originales, las funciones revisadas en el proyecto y documentación primaria de LitVM. Las instrucciones de juego se redactaron a partir de las escenas y módulos actuales, con capturas realizadas en un entorno de prueba aislado.','This edition brings together the vision from both original litepapers, features reviewed in the project and primary LitVM documentation. Gameplay instructions were written from the current scenes and modules, with screenshots captured in an isolated test environment.')+
`<ul class="source-list">${[
[sources.es,'Grassland Forest · Litepaper original en español','Grassland Forest · Original Spanish litepaper','Documentación del proyecto: visión, estadísticas, enlaces y vista previa.','Project documentation: vision, statistics, links and preview.'],
[sources.en,'Grassland Forest · Litepaper original en inglés','Grassland Forest · Original English litepaper','Nueve páginas revisadas; se armoniza su contenido con esta edición bilingüe.','Nine pages reviewed; their content is aligned with this bilingual edition.'],
[sources.roadmap,'Grassland Forest · Roadmap 2025–2026','Grassland Forest · 2025–2026 Roadmap','Fases, tareas y estados reproducidos del roadmap publicado; consulta: 16 de octubre de 2026.','Phases, tasks and statuses reproduced from the published roadmap; checked on 16 October 2026.'],
[sources.welcome,'LitVM Docs · Presentación','LitVM Docs · Welcome','Definición oficial del rollup y del ecosistema.','Official definition of the rollup and ecosystem.'],
[sources.architecture,'LitVM Docs · Arquitectura','LitVM Docs · Architecture','Componentes técnicos y fases de evolución hacia Litecoin.','Technical components and rollout phases toward Litecoin.'],
[sources.wallet,'LitVM Docs · Añadir a la cartera','LitVM Docs · Add to Your Wallet','Parámetros verificados de LiteForge y estado de testnet/mainnet.','Verified LiteForge parameters and testnet/mainnet status.'],
[sources.faq,'LitVM Docs · Preguntas frecuentes','LitVM Docs · FAQ','Moneda de gas, red de pruebas y estado del lanzamiento.','Gas currency, test network and launch status.'],
[sources.litvm,'LitVM · Sitio oficial','LitVM · Official website','Referencia pública del ecosistema LitVM.','Public reference for the LitVM ecosystem.']
].map(([url,a,b,c,d])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${t(a,b)} ↗</a><span>${t(c,d)}</span></li>`).join('')}</ul>`+
h('Criterio editorial','Editorial approach')+
p('La descripción del juego corresponde a las mascotas, los monstruos y los animales salvajes del mapa: puedes elegir ataque o defensa para tu mascota y combatir con la espada de tu personaje. La red corresponde a la configuración LitVM del proyecto revisado, y la guía de arena describe el combate en tiempo real. El roadmap conserva los estados publicados en su fuente, sin atribuir avances adicionales.','The game description covers pets, monsters and wild animals on the map: choose attack or defense for your pet and fight with your character’s sword. The network matches the reviewed project’s LitVM configuration, and the arena guide describes real-time combat. The roadmap preserves the statuses published in its source without claiming additional progress.')+
p('Las imágenes del juego y de su universo proceden del proyecto. Las capturas actualizadas de exploración, siembra, recolección, pesca, habilidades y enemigos usan datos de prueba del proyecto. La portada es una ilustración del universo.','Game and universe images come from the project. Updated screenshots of exploration, planting, gathering, fishing, skills and enemies use project test data. The cover is a universe illustration.')+
`<p class="note">${t('Edición: 16 de octubre de 2026 · Idiomas: español e inglés · Documento independiente.','Edition: 16 October 2026 · Languages: Spanish and English · Independent document.')}</p>`);

function render() {
  const toc=chapters.map((c,i)=>`<li><a href="#${c.id}" data-search="${esc(c.search)}"><span class="number">${String(i+1).padStart(2,'0')}</span><span>${t(c.es,c.en)}</span></a></li>`).join('');
  const content=chapters.map((c,i)=>`<section class="chapter" id="${c.id}" aria-labelledby="${c.id}-title"><p class="eyebrow">${String(i+1).padStart(2,'0')} / ${t('GRASSLAND FOREST · LITEPAPER','GRASSLAND FOREST · LITEPAPER')}</p><h2 id="${c.id}-title">${t(c.es,c.en)}</h2>${c.render()}</section>`).join('\n');
  return `<!doctype html>
<html lang="${lang}">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="color-scheme" content="light"><meta name="theme-color" content="#203b32">
<title>Grassland Forest — ${t('Litepaper en español','English Litepaper')} · LitVM</title>
<meta name="description" content="${esc(t('Litepaper ilustrado de Grassland Forest: aprende a comprar, cultivar, minar, pescar, construir, combatir y traducir el chat. Visión Web3 en LitVM LiteForge.','The illustrated Grassland Forest litepaper: learn to shop, farm, mine, fish, build, fight and translate chat. A Web3 vision on LitVM LiteForge.'))}">
<link rel="icon" href="assets/logo.webp" type="image/webp"><link rel="stylesheet" href="litepaper.css">
<link rel="alternate" hreflang="es" href="litepaper_español.html"><link rel="alternate" hreflang="en" href="litepaper_ingles.html"><script src="litepaper.js" defer></script>
</head>
<body>
<a class="skip" href="#contenido">${t('Saltar al contenido','Skip to content')}</a>
<header class="topbar"><div class="wrap"><a class="brand" href="#portada" aria-label="Grassland Forest"><img src="assets/logo.webp" alt="" width="51" height="51"><span><strong>Grassland Forest</strong><small>LITEPAPER · LITVM EDITION</small></span></a><div class="top-actions"><nav class="language" aria-label="${t('Idioma del documento','Document language')}"><a href="litepaper_español.html" lang="es" ${lang==='es'?'aria-current="page"':''}>ES</a><a href="litepaper_ingles.html" lang="en" ${lang==='en'?'aria-current="page"':''}>EN</a></nav><button class="print" type="button" aria-label="${t('Imprimir o guardar como PDF','Print or save as PDF')}"><span aria-hidden="true">↓</span> <span class="print-long">${t('Guardar / ','Save / ')}</span>PDF</button></div></div><div class="reading-progress" aria-hidden="true"></div></header>
<main class="wrap" id="portada">
<section class="hero" aria-labelledby="cover-title"><img src="assets/forest.webp" width="1672" height="941" alt="${t('Ilustración del bosque de Grassland Forest: cascadas, cabaña y un árbol iluminado.','Illustration of the Grassland Forest world: waterfalls, a cottage and an illuminated tree.')}" fetchpriority="high"><div class="hero-copy"><p class="eyebrow edition">${t('EL BOSQUE TIENE UNA HISTORIA. LA SIGUIENTE ES TUYA.','THE FOREST HAS A STORY. THE NEXT ONE IS YOURS.')}</p><h1 id="cover-title">${t('Cultiva tu mundo.<br><em>Vive la aventura.</em>','Grow your world.<br><em>Live the adventure.</em>')}</h1><p class="intro">${t('Un RPG de pixel art donde la granja, la exploración y las batallas se encuentran con Web3. Conoce el mundo, aprende a jugar y descubre nuestro horizonte en LitVM.','A pixel-art RPG where farming, exploration and battles meet Web3. Discover the world, learn to play and explore our horizon on LitVM.')}</p><a class="button" href="#vision">${t('Explorar el litepaper','Explore the litepaper')} <span aria-hidden="true">↘</span></a></div><span class="hero-corner">${t('Ilustración del universo · Edición 2026','Universe illustration · 2026 edition')}</span></section>
<div class="facts"><div class="fact"><b>${t('RPG · Vida y aventura','RPG · Life & adventure')}</b><span>${t('Granja, recursos y combate','Farming, resources and combat')}</span></div><div class="fact"><b>LitVM LiteForge</b><span>${t('Ecosistema Litecoin · Testnet','Litecoin ecosystem · Testnet')}</span></div><div class="fact"><b>${t('PC + móvil','PC + mobile')}</b><span>${t('Web y clientes · Según plataforma','Web and clients · By platform')}</span></div><div class="fact"><b>${t('16 octubre 2026','16 October 2026')}</b><span>${t('Edición ilustrada · Español','Illustrated edition · English')}</span></div></div>
<button type="button" class="menu-toggle" aria-expanded="false" aria-controls="document-nav">☰ ${t('Índice y búsqueda de capítulos','Contents and chapter search')}</button>
<div class="document"><aside class="sidebar" id="document-nav"><p class="eyebrow">${t('GUÍA DEL BOSQUE','FOREST FIELD GUIDE')}</p><label class="sr-only" for="chapter-search">${t('Buscar capítulos','Search chapters')}</label><input class="search" id="chapter-search" type="search" placeholder="${t('Buscar: pesca, PvP, chat…','Search: fishing, PvP, chat…')}" autocomplete="off"><p class="search-status" id="search-status" aria-live="polite"></p><nav aria-label="${t('Índice del litepaper','Litepaper contents')}"><ol class="toc">${toc}</ol></nav><p class="nav-note">${t('20 capítulos. Amplía las capturas para ver los detalles. Usa PDF para imprimir o guardar esta edición.','20 chapters. Enlarge screenshots to see details. Use PDF to print or save this edition.')}</p></aside>
<article class="article" id="contenido" aria-label="${t('Litepaper de Grassland Forest','Grassland Forest litepaper')}">${content}</article></div>
<footer class="footer"><span>© 2026 Grassland Forest · ${t('El bosque continúa.','The forest continues.')}<br>${t('Litepaper independiente · Edición LitVM','Independent litepaper · LitVM edition')}</span><a href="${lang==='es'?'litepaper_ingles.html':'litepaper_español.html'}" lang="${lang==='es'?'en':'es'}">${t('Read this litepaper in English ↗','Leer este litepaper en español ↗')}</a></footer>
</main><a href="#portada" class="to-top" aria-label="${t('Volver al inicio','Back to top')}">↑</a>
<dialog class="lightbox" id="image-dialog" aria-label="${t('Imagen ampliada','Enlarged image')}"><button type="button">${t('Cerrar','Close')} ✕</button><img alt=""><p></p></dialog>
</body></html>`;
}
for(lang of ['es','en']){const file=lang==='es'?'litepaper_español.html':'litepaper_ingles.html';const html=render();fs.writeFileSync(path.join(root,file),html,'utf8');console.log(file,Buffer.byteLength(html),'bytes',chapters.length,'chapters');}
